tr -d '
' < /tmp/sup.b64 | base64 -d | gunzip > /tmp/sup.py || {
  echo "DEPLOY_FAIL decode"; exit 1; }
GOT=$(sha256sum /tmp/sup.py | cut -d' ' -f1)
echo "want=$WANT"
echo "got =$GOT"
if [ "$GOT" != "$WANT" ]; then echo "DEPLOY_FAIL digest mismatch"; exit 1; fi
python3 -c "import ast,sys; ast.parse(open('/tmp/sup.py',encoding='utf-8').read())" || {
  echo "DEPLOY_FAIL not valid python"; exit 1; }

cp -a "$DST" "$DST.bak.$STAMP" 2>/dev/null || true
cp /tmp/sup.py "$DST"
# Files written over SSM land root:root and the supervisor runs as ec2-user.
chown ec2-user:ec2-user "$DST"
chmod 644 "$DST"
echo "deployed_sha=$(sha256sum "$DST" | cut -d' ' -f1)"
echo "wired=$(grep -c 'order_replay_candidates' "$DST")"
echo "stall_kind=$(grep -c 'deferred_replay_interrupted_before_gate' "$DST")"

echo "--- before ---"
df -h /srv/wizard | tail -1
systemctl show wizard-curriculum-supervisor.service -p ActiveState -p SubState -p NRestarts --no-pager
cat /srv/wizard/runtime/programming-integrated-20260713/deferred-replay-active.json 2>/dev/null | head -c 300; echo

systemctl restart wizard-curriculum-supervisor.service
sleep 45

echo "--- after ---"
systemctl show wizard-curriculum-supervisor.service -p ActiveState -p SubState -p NRestarts --no-pager
df -h /srv/wizard | tail -1
echo "--- stall records ---"
grep -c 'deferred_replay_interrupted_before_gate'   /srv/wizard/runtime/programming-integrated-20260713/curriculum-health.jsonl || echo 0
echo "--- active interval now ---"
cat /srv/wizard/runtime/programming-integrated-20260713/deferred-replay-active.json 2>/dev/null | head -c 400; echo
echo "--- status ---"
tail -c 400 /srv/wizard/runtime/programming-integrated-20260713/curriculum-supervisor.status.json
echo
echo DEPLOY_OK
